#define NOMINMAX
#include <windows.h>
#include <filesystem>
#include <string>
#include <iostream>
int wmain(){wchar_t loaded[32768]{},longName[32768]{},finalName[32768]{};DWORD n=GetModuleFileNameW(nullptr,loaded,32768);if(!n||n>=32768)return 2;HANDLE h=CreateFileW(loaded,GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT,nullptr);if(h==INVALID_HANDLE_VALUE)return 3;BY_HANDLE_FILE_INFORMATION info{};bool valid=GetFileInformationByHandle(h,&info)!=FALSE;DWORD f=GetFinalPathNameByHandleW(h,finalName,32768,FILE_NAME_NORMALIZED);CloseHandle(h);DWORD l=GetLongPathNameW(loaded,longName,32768);if(!valid||!f||f>=32768||!l||l>=32768)return 4;std::wstring final=finalName;if(final.rfind(L"\\\\?\\",0)==0)final.erase(0,4);bool equal=CompareStringOrdinal(loaded,-1,final.c_str(),-1,TRUE)==CSTR_EQUAL;bool expansionEqual=CompareStringOrdinal(longName,-1,final.c_str(),-1,TRUE)==CSTR_EQUAL;bool parentLink=false,parentUnknown=false;for(auto p=std::filesystem::path(loaded).parent_path();!p.empty();p=p.parent_path()){DWORD a=GetFileAttributesW(p.c_str());if(a==INVALID_FILE_ATTRIBUTES)parentUnknown=true;else if(a&FILE_ATTRIBUTE_REPARSE_POINT)parentLink=true;if(p==p.root_path())break;}std::cout<<"{\"loadedDiffersFromPhysical\":"<<(equal?"false":"true")<<",\"longExpansionMatchesPhysical\":"<<(expansionEqual?"true":"false")<<",\"loadedContainsTilde\":"<<(std::wstring(loaded).find(L'~')!=std::wstring::npos?"true":"false")<<",\"leafReparse\":"<<((info.dwFileAttributes&FILE_ATTRIBUTE_REPARSE_POINT)?"true":"false")<<",\"singleLink\":"<<(info.nNumberOfLinks==1?"true":"false")<<",\"ancestorReparse\":"<<(parentLink?"true":"false")<<",\"ancestorUnknown\":"<<(parentUnknown?"true":"false")<<"}\n";return 0;}
